import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.CrXGS008.js";const k=JSON.parse('{"title":"HTTP-API","description":"","frontmatter":{},"headers":[],"relativePath":"de/nay-lib/api.md","filePath":"de/nay-lib/api.md"}'),n={name:"de/nay-lib/api.md"};function d(o,e,r,l,p,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="http-api" tabindex="-1">HTTP-API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP-API&quot;">​</a></h1><p>Skripte und Websites (Dashboards, Discord-Bots, Shops) können den Server über eine JSON-API lesen und ändern, die FXServer auf dem Spielport bereitstellt:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;server ip&gt;:&lt;port&gt;/&lt;resource&gt;/v1/&lt;route&gt;</span></span></code></pre></div><h2 id="aktivieren" tabindex="-1">Aktivieren <a class="header-anchor" href="#aktivieren" aria-label="Permalink to &quot;Aktivieren&quot;">​</a></h2><p>Die API ist <strong>standardmäßig aus</strong>. Aktiviere sie in <code>/nay</code> auf der Seite <strong>Nayretis</strong>: <strong>HTTP-API</strong> (<code>ApiEnabled</code>). Solange sie aus ist, antwortet jede Route mit <code>503 api_disabled</code>. <strong>Maximale Anfragegröße (KB)</strong> (<code>ApiMaxBodyKb</code>) begrenzt den Anfrageinhalt (standardmäßig 1024 KB).</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><p>Erstelle Tokens im Tab <strong>API</strong> von <code>/nay</code> (das Token wird nur einmal angezeigt: kopiere es sofort) oder über die Serverkonsole:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_api_token create &lt;label&gt; &lt;scope...&gt;</span></span>
<span class="line"><span>nay_api_token list</span></span>
<span class="line"><span>nay_api_token revoke &lt;id&gt;</span></span></code></pre></div><p>Ein Token sieht so aus: <code>nay_&lt;id&gt;_&lt;secret&gt;</code>. Gespeichert wird nur sein SHA-256-Hash. Jedes Token hat seine Scopes, optional erlaubte Adressen (IPv4, IPv6 oder CIDR-Bereiche), ein Anfragelimit pro Minute und ein optionales Ablaufdatum.</p><p>Scopes haben die Form <code>&lt;resource&gt;.&lt;scope&gt;</code>, mit Platzhaltern: <code>nay_car_wash.*</code> gibt jede Route eines Skripts frei, <code>*</code> gibt alles frei. Jedes Skript listet seine Routen und Scopes auf seiner eigenen Seite, zum Beispiel <a href="/de/car-wash/api">Car Wash</a>.</p><h2 id="anfragen" tabindex="-1">Anfragen <a class="header-anchor" href="#anfragen" aria-label="Permalink to &quot;Anfragen&quot;">​</a></h2><ul><li>Sende <code>Authorization: Bearer &lt;token&gt;</code>.</li><li>Anfrageinhalte sind JSON (<code>Content-Type: application/json</code>) mit einem <code>Content-Length</code>. Inhalte in Chunks werden abgelehnt.</li><li>Nach 10 fehlgeschlagenen Authentifizierungen innerhalb einer Minute werden Anfragen ohne gültiges Token von dieser Adresse 5 Minuten lang abgelehnt. Gültige Tokens funktionieren weiter.</li><li>Hinter einem Reverse Proxy setzt du <code>nay:apiTrustedProxies</code> (siehe <a href="#https">HTTPS</a>). Sonst teilen sich alle Aufrufer die Adresse des Proxys.</li></ul><p>Jede Antwort ist JSON mit einem Header <code>X-Request-Id</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;forbidden&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;This token does not allow this route&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } } }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>Code</th><th>Bedeutung</th></tr></thead><tbody><tr><td>400</td><td><code>unexpected_body</code>, <code>invalid_json</code>, <code>invalid_request</code></td><td>Inhalt an eine Route ohne Inhalt gesendet, Inhalt kein gültiges JSON oder fehlerhafter <code>Content-Length</code>.</td></tr><tr><td>401</td><td><code>unauthorized</code></td><td>Token fehlt, ist unbekannt, widerrufen oder abgelaufen.</td></tr><tr><td>403</td><td><code>forbidden</code>, <code>ip_not_allowed</code></td><td>Dem Token fehlt der Scope, oder die Adresse ist für dieses Token nicht erlaubt.</td></tr><tr><td>404 / 405</td><td><code>not_found</code>, <code>method_not_allowed</code></td><td>Unbekannte Route oder falsche Methode für eine bekannte Route.</td></tr><tr><td>411</td><td><code>length_required</code></td><td>Jedes <code>Transfer-Encoding</code> (Inhalt in Chunks).</td></tr><tr><td>413</td><td><code>payload_too_large</code></td><td>Inhalt größer als <code>ApiMaxBodyKb</code>. Ein angekündigter <code>Content-Length</code> über 10 MB wird abgelehnt, bevor der Inhalt gelesen wird.</td></tr><tr><td>415</td><td><code>unsupported_media_type</code></td><td>Inhalt, der nicht <code>application/json</code> ist.</td></tr><tr><td>422</td><td><code>invalid_request</code>, <code>unknown_parameter</code>, <code>invalid_value</code></td><td>Parameter, Query oder Inhalt besteht die Prüfung nicht (<code>details.path</code> und <code>details.reason</code>).</td></tr><tr><td>429</td><td><code>rate_limited</code>, <code>too_many_failures</code></td><td>Token über seinem Limit pro Minute oder Adresse gesperrt. Siehe <code>Retry-After</code>.</td></tr><tr><td>500</td><td><code>internal_error</code></td><td>Die Route ist fehlgeschlagen. Siehe Serverkonsole.</td></tr><tr><td>503</td><td><code>api_disabled</code>, <code>not_ready</code></td><td>API aus oder Ressource startet noch (<code>Retry-After</code>).</td></tr><tr><td>504</td><td><code>timeout</code></td><td>Die Route hat nicht innerhalb von 10 Sekunden geantwortet. Sie läuft weiter: Eine Änderung kann nach dem 504 noch angewendet werden, lies den Zustand also erneut, bevor du es noch einmal versuchst.</td></tr></tbody></table><h2 id="routen-von-nay-lib" tabindex="-1">Routen von nay_lib <a class="header-anchor" href="#routen-von-nay-lib" aria-label="Permalink to &quot;Routen von nay_lib&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Methode</th><th>Route</th><th>Scope</th><th>Daten</th></tr></thead><tbody><tr><td>GET</td><td><code>/nay_lib/v1/status</code></td><td><code>nay.status</code></td><td>Servername, Spieler, maximale Spieler, Framework, Inventar, Target, Nayretis Ressourcen und Versionen.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/players</code></td><td><code>nay.players</code></td><td>Verbundene Spieler: ID, Name, Charakter, Kennung, Job.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/settings/:resource</code></td><td><code>nay.settings</code> plus <code>&lt;resource&gt;.config</code> oder <code>nay.config</code></td><td>Einstellungen eines Skripts mit ihren Werten.</td></tr><tr><td>PUT</td><td><code>/nay_lib/v1/settings/:resource/:key</code></td><td>wie oben</td><td>Ändert eine Einstellung. Inhalt <code>{ &quot;value&quot;: ... }</code>.</td></tr><tr><td>DELETE</td><td><code>/nay_lib/v1/settings/:resource/:key</code></td><td>wie oben</td><td>Setzt eine Einstellung auf ihren Standardwert zurück.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/audit</code></td><td><code>nay.audit</code></td><td>Protokoll, 50 Einträge pro Seite. Query <code>resource</code>, <code>action</code>, <code>actor</code>, <code>from</code> und <code>to</code> (Unix-Sekunden), <code>page</code>.</td></tr></tbody></table><p>Jeder Aufruf, der etwas ändert, wird ins <a href="/de/nay-lib/audit">Protokoll</a> geschrieben (<code>api.call</code>, Urheber <code>api:&lt;token label&gt;</code>).</p><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>FXServer spricht nur unverschlüsseltes HTTP: Jeder auf dem Übertragungsweg kann ein so gesendetes Token mitlesen. Setze einen Reverse Proxy mit Zertifikat vor die API und gib nur die Routen frei, die du nutzt. Teile <code>nay_lib</code> dann mit, welchen Proxys es vertrauen soll, damit erlaubte Adressen und Anfragelimits für die echte Client-Adresse aus <code>X-Forwarded-For</code> gelten:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set nay:apiTrustedProxies &quot;127.0.0.1&quot;</span></span></code></pre></div><p>Der Wert ist eine durch Kommas getrennte Liste von Adressen oder CIDR-Bereichen.</p><p>nginx:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api.example.com;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/api.example.com/fullchain.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/api.example.com/privkey.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	location</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ~</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;"> ^/(nay_lib|nay_car_wash)/v1/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:30120;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		client_max_body_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1m</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Caddy (Zertifikat wird automatisch bezogen):</p><div class="language-caddy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com {</span></span>
<span class="line"><span>	@nayretis path_regexp ^/(nay_lib|nay_car_wash)/v1/</span></span>
<span class="line"><span>	reverse_proxy @nayretis 127.0.0.1:30120</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,26)])])}const u=t(n,[["render",d]]);export{k as __pageData,u as default};
